import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import LinkButton from 'flarum/common/components/LinkButton';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { duration } from '../format';

/**
 * Who plays this server most.
 *
 * 🚨 The names are people you can reply to, and that is the entire point. A
 * leaderboard of in-game names is something any game panel can show; one where
 * the names link to forum profiles — because those players proved who they are
 * — is the thing only a panel living inside a community can do.
 */
export default class Leaderboard extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    this.rows = null;
    this.failed = false;
    this.load();
  }
  load() {
    app.request({
      method: 'GET',
      url: app.forum.attribute('apiUrl') + `/garrison/servers/${this.attrs.server.id}/leaderboard`
    }).then(res => {
      this.rows = res && res.data || [];
      m.redraw();
    }).catch(() => {
      this.failed = true;
      m.redraw();
    });
  }
  view() {
    if (this.failed) return null;
    if (this.rows === null) {
      return m("section", {
        className: "GarrisonBoard"
      }, m(LoadingIndicator, {
        display: "inline",
        size: "small"
      }));
    }

    // A server nobody has played yet gets nothing, not an empty table.
    if (this.rows.length === 0) return null;
    return m("section", {
      className: "GarrisonBoard"
    }, m("h3", null, app.translator.trans('ernestdefoe-garrison.forum.board.title')), m("ol", {
      className: "GarrisonBoard-list"
    }, this.rows.map(r => m("li", {
      className: 'GarrisonBoard-row' + (r.online ? ' is-online' : ''),
      key: r.player
    }, r.online ? m("span", {
      className: "GarrisonBoard-dot",
      title: app.translator.trans('ernestdefoe-garrison.forum.board.online')
    }) : null, m("span", {
      className: "GarrisonBoard-who"
    }, r.username ? LinkButton.component({
      href: app.route('user', {
        username: r.username
      }),
      className: 'Button Button--link'
    }, r.displayName || r.username) : r.player), r.username && r.displayName !== r.player ? m("span", {
      className: "GarrisonBoard-alias"
    }, r.player) : null, m("span", {
      className: "GarrisonBoard-time"
    }, duration(r.seconds))))));
  }
}
flarum.reg.add('ernestdefoe-garrison', 'forum/components/Leaderboard', Leaderboard);